headers={'User-Agent':'Mozilla/5.0'}
home=requests.get('https://sanketoan.vn/',timeout=20,headers=headers).text
urls=[]
for u in re.findall(r'href=["\'](https://sanketoan.vn/cong-viec/[^"\']+)', home):
    if u not in urls:
        urls.append(u)
urls=urls[:10]
rows=[]
for idx,u in enumerate(urls,1):
    text=requests.get(u,timeout=20,headers=headers).text
    def clean(s):
        s=html.unescape(re.sub(r'<[^>]+>',' ',s or ''))
        s=re.sub(r'\s+',' ',s).strip(' :\n\t')
        return s
    title=clean(re.search(r'<h1[^>]*class="title_job"[^>]*>(.*?)</h1>',text,re.I|re.S).group(1))
    company=clean(re.search(r'class="titleCompanyName[^"]*"[^>]*>(.*?)</a>',text,re.I|re.S).group(1))
    loc=''
    m=re.search(r'Địa điểm làm việc\s*:([^<]{1,300})</p>',text,re.I|re.S)
    if m: loc=clean(m.group(1))
    salary=''
    m=re.search(r'Mức lương\s*:([^<]{1,200})</p>',text,re.I|re.S)
    if m: salary=clean(m.group(1))
    exp=''
    m=re.search(r'Kinh nghiệm\s*:([^<]{1,200})</p>',text,re.I|re.S)
    if m: exp=clean(m.group(1))
    degree=''
    m=re.search(r'Trình độ\s*:([^<]{1,200})</p>',text,re.I|re.S)
    if m: degree=clean(m.group(1))
    deadline=''
    m=re.search(r'Hạn nộp hồ\s*sơ:\s*([0-9]{2}/[0-9]{2}/[0-9]{4})',text,re.I)
    if m:
        deadline=datetime.strptime(m.group(1),'%d/%m/%Y').date().isoformat()
    rel=''
    m=re.search(r'Ngày đăng tin\s*:\s*([^<]+)</span>',text,re.I|re.S)
    if m:
        rel=clean(m.group(1))
    pub=''
    if rel:
        r=rel.lower()
        if 'giờ trước' in r:
            pub=TODAY.isoformat()
        else:
            m2=re.search(r'(\d+)\s+ngày trước',r)
            m3=re.search(r'(\d+)\s+tuần trước',r)
            if m2: pub=(TODAY-timedelta(days=int(m2.group(1)))).isoformat()
            elif m3: pub=(TODAY-timedelta(days=int(m3.group(1))*7)).isoformat()
            else: pub=TODAY.isoformat()
    slug_title=title.lower().replace('tuyển dụng ','').strip()
    rows.append({'idx':idx,'url':u,'title':title,'company':company,'location':loc,'salary':salary,'experience':exp,'degree':degree,'deadline':deadline,'publishDate':pub,'relativeDate':rel})
Path('.m/reclass/jobs-seed-batch01-review.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
